1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using Microsoft.Extensions.ML;
4. 
5. var builder = WebApplication.CreateBuilder(args);
6. 
7. // Train the model at startup
8. var mlContext = new MLContext(seed: 42);
9. var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
10. 
11. var data = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
12. var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
13. 
14. var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
15.     .Append(mlContext.Transforms.Concatenate("Features",
16.         nameof(CustomerData.Age),
17.         nameof(CustomerData.Income),
18.         "RegionEncoded",
19.         nameof(CustomerData.PurchaseHistory)))
20.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
21.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
22.         labelColumnName: "Label",
23.         featureColumnName: "Features"));
24. 
25. var model = pipeline.Fit(split.TrainSet);
26. 
27. // Evaluate on the test set; fall back to train set if test set is too small
28. var testData = split.TestSet;
29. var testCount = mlContext.Data.CreateEnumerable<CustomerData>(testData, reuseRowObject: false).Count();
30. var posCount = mlContext.Data.CreateEnumerable<CustomerData>(testData, reuseRowObject: false).Count(c => c.Churned);
31. 
32. if (testCount < 2 || posCount == 0)
33. {
34.     Console.WriteLine($"Test set too small ({testCount} rows, {posCount} positive) — evaluating on training data instead.");
35.     Console.WriteLine("Add more rows to Data/customers.csv for reliable evaluation.");
36.     testData = split.TrainSet;
37. }
38. 
39. var predictions = model.Transform(testData);
40. var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
41. Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
42. 
43. // Save the model
44. var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
45. mlContext.Model.Save(model, data.Schema, modelPath);
46. 
47. // Register pooled prediction engine for thread-safe predictions
48. builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
49.     .FromFile(modelPath);
50. 
51. var app = builder.Build();
52. 
53. app.MapGet("/", () => "Churn Predictor API — POST to /predict");
54. 
55. app.MapPost("/predict", (
56.     PredictionEnginePool<CustomerData, ChurnPrediction> pool,
57.     CustomerData customer) =>
58. {
59.     var prediction = pool.Predict(customer);
60.     return Results.Ok(new
61.     {
62.         WillChurn = prediction.PredictedLabel,
63.         Confidence = prediction.Probability
64.     });
65. });
66. 
67. app.Run();
68. 
