70. public class CustomerData
71. {
72.     [LoadColumn(0)] public float Age { get; set; }
73.     [LoadColumn(1)] public float Income { get; set; }
74.     [LoadColumn(2)] public string Region { get; set; } = string.Empty;
75.     [LoadColumn(3)] public float PurchaseHistory { get; set; }
76.     [LoadColumn(4), ColumnName("Label")] public bool Churned { get; set; }
77. }
78. 
